{
  "headline": "FDA's records trace our supply to a plant classified VAI 610 days before the 2021 shortage posting and VAI 728 days after",
  "headline_cites": ["D9", "D10"],
  "sentences": [
    {
      "text": "Gentamicin sulfate is not on FDA's current shortage list as of 2026-10-21; FDA's history shows an earlier shortage first posted on 2021-07-23, since resolved.",
      "cites": ["D11"]
    },
    {
      "text": "FDA inspection 1110899 at Hospira, Inc. (FEI 1021343) ended 2019-11-21, classified VAI; classification letter 2020-02-12 — 610 days before FDA posted the shortage on 2021-07-23.",
      "cites": ["D9", "E20"]
    },
    {
      "text": "FDA inspection 1210546 at Cosette Pharmaceuticals NC Laboratories, LLC (FEI 1053439) ended 2023-07-21, classified VAI; classification letter 2023-08-25 — 728 days after FDA posted the shortage on 2021-07-23.",
      "cites": ["D10", "E23"]
    },
    {
      "text": "Our Corvale General and Corvale East sites both use NDC 00409120703 labeled by Hospira, Inc., which names Hospira, Inc. as a registered plant (FEI 1021343) last inspected NAI 2025-02-07.",
      "cites": ["E6", "E2", "E22"]
    },
    {
      "text": "Corvale East holds 31 vials of 40 mg/mL, 2 mL at 15.3 per day: 2 days on hand; Corvale General holds 244 vials at 16.3 per day: 15 days on hand.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The rule selects transferring 16 vials of 40 mg/mL, 2 mL from Corvale General to Corvale East; Corvale General can spare 16 vials while keeping two weeks, and Corvale East would reach 3 days.",
      "cites": ["D12"]
    },
    {
      "text": "Check whether any FDA action occurred at the registered plant before the 2021 posting, and verify current supply from alternate manufacturers not on the shortage list today.",
      "cites": ["D13", "D14"]
    }
  ]
}
